// Command Stripe-cli is a CLI + REPL for the Stripe SDK,
// built on the boru engine. Positional arguments are joined into a
// single boru expression and evaluated; with no arguments, falls into
// a REPL. Generated by sdkgen go-cli target.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	eng "github.com/boru-lang/boru/eng/go"
	"github.com/boru-lang/boru/eng/go/parser"
	sdk "github.com/voxgig-sdk/stripe-sdk/go"
)

// prompt is the REPL prompt prefix (matches the SDK slug).
const prompt = "stripe"

// entitiesHelp is the space-separated entity list shown by /help.
const entitiesHelp = "account account_link account_owner account_session active_entitlement alert apple_pay_domain application_fee association authentication authorization balance balance_setting balance_transaction bank_account calculation capability card cardholder cash_balance cash_balance_transaction charge configuration confirmation_token connection_token country_spec coupon credit_balance_summary credit_balance_transaction credit_grant credit_note credit_note_line credit_reversal customer customer_balance_transaction customer_session debit_reversal deleted_account deleted_apple_pay_domain deleted_coupon deleted_external_account deleted_invoiceitem deleted_person deleted_plan deleted_product_feature deleted_subscription_item deleted_webhook_endpoint discount dispute domain early_fraud_warning ephemeral_key event exchange_rate external_account feature feedback_option file file_link financial_account financial_account_feature fund_cash_balance funding_instruction history inbound_transfer install invoice invoice_payment invoice_rendering_template invoiceitem line line_item linked_account linked_account_owner location login_link mandate meter meter_event meter_event_adjustment meter_event_summary onboarding_link order outbound_payment outbound_transfer payment_attempt_record payment_evaluation payment_intent payment_intent_amount_details_line_item payment_link payment_method payment_method_configuration payment_method_domain payment_record payout person personalization_design physical_bundle plan price product product_feature promotion_code quote quote_computed_upfront_line_item quote_pdf reader received_credit received_debit refund registration report_run report_type request reversal review scheduled_query_run search secret session setting settlement setup_attempt setup_intent shipping_rate sigma_api_query source source_mandate_notification source_transaction subscription subscription_item subscription_schedule supplier tax_code tax_id tax_rate test_clock token topup transaction transaction_entry transfer trial_offer value_list value_list_item verification_report verification_session webhook_endpoint"

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// usage prints the CLI help (for --help / -h). No client or network setup.
func usage(out io.Writer) {
	fmt.Fprintf(out, "%s-cli — boru-driven CLI + REPL for the %s SDK\n\n", prompt, prompt)
	fmt.Fprintln(out, "Usage:")
	fmt.Fprintf(out, "  %s-cli [--help] [<boru expression>]\n\n", prompt)
	fmt.Fprintln(out, "With arguments, they are joined into a single boru expression and")
	fmt.Fprintln(out, "evaluated against the API. With no arguments, starts an interactive REPL.")
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Words:    list / load / update <query?> <entity>")
	fmt.Fprintln(out, "Entities:", entitiesHelp)
	fmt.Fprintln(out, "Env:      STRIPE_APIKEY (api key), STRIPE_BASE (base url override)")
	fmt.Fprintln(out, "REPL:     /help  /quit")
}

func run(args []string, in io.Reader, out, errOut io.Writer) int {
	// --help / -h: print usage and exit before any config or network setup.
	for _, a := range args {
		if a == "--help" || a == "-h" {
			usage(out)
			return 0
		}
	}

	// Configure from the environment: STRIPE_APIKEY carries the API key and
	// STRIPE_BASE optionally overrides the API base URL (e.g. production).
	// Both injectable by a secrets vault. Unset -> nil config defaults.
	var opts map[string]any
	if apikey := os.Getenv("STRIPE_APIKEY"); apikey != "" {
		opts = map[string]any{"apikey": apikey}
	}
	if base := os.Getenv("STRIPE_BASE"); base != "" {
		if opts == nil {
			opts = map[string]any{}
		}
		opts["base"] = base
	}
	client := sdk.NewStripeSDK(opts)

	r, err := eng.NewRegistry()
	if err != nil {
		fmt.Fprintf(errOut, "registry: %v\n", err)
		return 1
	}
	registerSDKWords(r, client)
	if err := r.Err(); err != nil {
		fmt.Fprintf(errOut, "word registration: %v\n", err)
		return 1
	}
	r.SetParseFunc(parser.Parse)
	r.InitRootContext()
	r.MarkReady()

	if len(args) > 0 {
		return evalOnce(r, strings.Join(args, " "), out, errOut)
	}
	repl(r, in, out)
	return 0
}

func evalOnce(r *eng.Registry, src string, out, errOut io.Writer) int {
	values, err := parser.Parse(src)
	if err != nil {
		fmt.Fprintf(errOut, "parse: %v\n", err)
		return 1
	}
	result, err := eng.NewTop(r).Run(values)
	if err != nil {
		fmt.Fprintf(errOut, "error: %v\n", err)
		return 1
	}
	for _, v := range result {
		fmt.Fprintln(out, v.String())
	}
	return 0
}

func repl(r *eng.Registry, in io.Reader, out io.Writer) {
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for {
		fmt.Fprintf(out, "%s> ", prompt)
		if !scanner.Scan() {
			fmt.Fprintln(out)
			return
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		switch line {
		case "/quit", "/q", "/exit":
			return
		case "/help", "/h", "/?":
			fmt.Fprintln(out, "words:    list / load / update <query?> <entity>")
			fmt.Fprintln(out, "entities:", entitiesHelp)
			fmt.Fprintln(out, "meta:     /help  /quit")
			continue
		}
		values, err := parser.Parse(line)
		if err != nil {
			fmt.Fprintf(out, "  parse error: %v\n", err)
			continue
		}
		result, err := eng.NewTop(r).Run(values)
		if err != nil {
			fmt.Fprintf(out, "  error: %v\n", err)
			continue
		}
		for _, v := range result {
			fmt.Fprintln(out, v.String())
		}
	}
}
